public class FolderEntryTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        FolderEntry empty = new FolderEntry("empty");
        check("empty folder name", "empty", empty.name());
        check("empty folder file count", 0, empty.fileCount());
        check("empty folder depth", 1, empty.depth());

        FolderEntry sub = new FolderEntry("sub");
        sub.add(new FileEntry("b.txt", 50));
        FolderEntry root = new FolderEntry("root");
        root.add(new FileEntry("a.txt", 100)).add(sub);

        check("add returns the folder for chaining", "root",
              new FolderEntry("root").add(new FileEntry("x", 1)).name());
        check("total size across two levels", 150, root.totalSize());
        check("file count across two levels", 2, root.fileCount());
        check("depth across two levels", 2, root.depth());

        FolderEntry deep = new FolderEntry("deep");
        deep.add(new FileEntry("c.txt", 7));
        sub.add(deep);
        check("total size across three levels", 157, root.totalSize());
        check("file count across three levels", 3, root.fileCount());
        check("depth across three levels", 3, root.depth());
        check("a folder is also an Entry", 57, ((Entry) sub).totalSize());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

