import java.util.ArrayList;
import java.util.List;

interface Entry {

    String name();

    int totalSize();
}

final class FileEntry implements Entry {

    private final String name;
    private final int size;

    FileEntry(String name, int size) {
        this.name = name;
        this.size = size;
    }

    @Override
    public String name() {
        return name;
    }

    @Override
    public int totalSize() {
        return size;
    }
}

public class FolderEntry implements Entry {

    private final String name;
    private final List<Entry> children = new ArrayList<>();

    public FolderEntry(String name) {
        this.name = name;
    }

    @Override
    public String name() {
        return name;
    }

    public FolderEntry add(Entry child) {
        children.add(child);
        return this;
    }

    @Override
    public int totalSize() {
        int total = 0;
        for (Entry child : children) {
            total += child.totalSize();
        }
        return total;
    }

    public int fileCount() {
        int count = 0;
        for (Entry child : children) {
            if (child instanceof FolderEntry) {
                count += ((FolderEntry) child).fileCount();
            } else {
                count++;
            }
        }
        return count;
    }

    public int depth() {
        int deepest = 0;
        for (Entry child : children) {
            if (child instanceof FolderEntry) {
                deepest = Math.max(deepest, ((FolderEntry) child).depth());
            }
        }
        return 1 + deepest;
    }
}
